// Extract parameters from webhook body
const body = $input.item.json.body || $input.item.json;

const topic = body.topic || 'Artificial Intelligence trends 2024';
const searchDepth = body.searchDepth || 'advanced';
const maxResults = body.maxResults || 10;

return {
  json: {
    topic: topic,
    searchDepth: searchDepth,
    maxResults: maxResults
  }
};

// Parse the output from the research script
const stdout = $input.item.json.stdout || '';
const stderr = $input.item.json.stderr || '';
const exitCode = $input.item.json.exitCode || 0;

// Extract JSON output from stdout (last JSON block)
let result = null;
try {
  // Find the last occurrence of JSON output
  const lines = stdout.split('\n');
  let jsonStr = '';
  let inJson = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line === 'JSON Output:') {
      inJson = true;
      jsonStr = '';
      continue;
    }
    if (inJson) {
      jsonStr += line;
    }
  }

  if (jsonStr) {
    result = JSON.parse(jsonStr);
  }
} catch (error) {
  // If parsing fails, try to find any JSON in the output
  try {
    const jsonMatch = stdout.match(/\{[\s\S]*"success"[\s\S]*\}/g);
    if (jsonMatch && jsonMatch.length > 0) {
      result = JSON.parse(jsonMatch[jsonMatch.length - 1]);
    }
  } catch (e) {
    // Still failed
  }
}

// If no result was parsed, create error result
if (!result) {
  result = {
    success: exitCode === 0,
    error: stderr || (exitCode !== 0 ? 'Script execution failed' : null),
    stdout: stdout.substring(0, 500),
    stderr: stderr.substring(0, 500),
    exitCode: exitCode
  };
}

return {
  json: result
};
